package com.example.circleoverlay;
import android.app.Service; import android.content.Intent; import android.graphics.Canvas; import android.graphics.Paint; import android.graphics.Color; import android.graphics.RectF; import android.os.IBinder; import android.os.Handler; import android.view.WindowManager; import android.view.Gravity; import android.view.View; import android.view.WindowManager.LayoutParams; import android.widget.*; import android.graphics.PixelFormat; import android.provider.Settings; import android.content.Context;
public class OverlayService extends Service {
 WindowManager wm; View panel; CircleView circle; WindowManager.LayoutParams panelLp,circleLp; Handler handler=new Handler(); int radius=240,seconds=8; boolean anim=false;
 public IBinder onBind(Intent i){return null;} public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);showCircle();showPanel();}
 int overlayType(){return LayoutParams.TYPE_APPLICATION_OVERLAY;}
 void showCircle(){circle=new CircleView(this);circleLp=new LayoutParams(LayoutParams.MATCH_PARENT,LayoutParams.MATCH_PARENT,overlayType(),LayoutParams.FLAG_NOT_FOCUSABLE|LayoutParams.FLAG_NOT_TOUCHABLE|LayoutParams.FLAG_LAYOUT_IN_SCREEN|LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);circleLp.gravity=Gravity.TOP|Gravity.LEFT;wm.addView(circle,circleLp);}
 void showPanel(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(16,12,16,12);box.setBackgroundColor(0xdd202a20); TextView head=new TextView(this);head.setText("CIRCLE OVERLAY  •  drag panel");head.setTextColor(Color.WHITE);box.addView(head);
 TextView rLabel=new TextView(this);rLabel.setTextColor(Color.WHITE);rLabel.setText("Radius: "+radius+" px");box.addView(rLabel);SeekBar r=new SeekBar(this);r.setMax(600);r.setProgress(radius);box.addView(r);r.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){radius=Math.max(30,p);rLabel.setText("Radius: "+radius+" px");circle.invalidate();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
 TextView tLabel=new TextView(this);tLabel.setTextColor(Color.WHITE);tLabel.setText("Draw time: "+seconds+" sec");box.addView(tLabel);SeekBar t=new SeekBar(this);t.setMax(58);t.setProgress(seconds-2);box.addView(t);t.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){seconds=p+2;tLabel.setText("Draw time: "+seconds+" sec");}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
 Button draw=new Button(this);draw.setText("DRAW CIRCLE");draw.setOnClickListener(v->{circle.startAnimation(seconds);if(CircleAccessibilityService.instance!=null)CircleAccessibilityService.drawCircle(radius,seconds*1000);else Toast.makeText(this,"Enable accessibility service first",Toast.LENGTH_LONG).show();});box.addView(draw);
 Button close=new Button(this);close.setText("Close overlay");close.setOnClickListener(v->stopSelf());box.addView(close);panel=box;panelLp=new LayoutParams(LayoutParams.WRAP_CONTENT,LayoutParams.WRAP_CONTENT,overlayType(),LayoutParams.FLAG_NOT_FOCUSABLE|LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);panelLp.gravity=Gravity.TOP|Gravity.LEFT;panelLp.x=20;panelLp.y=120;wm.addView(panel,panelLp);head.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){sx=e.getRawX();sy=e.getRawY();ox=panelLp.x;oy=panelLp.y;return true;}if(e.getAction()==2){panelLp.x=ox+(int)(e.getRawX()-sx);panelLp.y=oy+(int)(e.getRawY()-sy);wm.updateViewLayout(panel,panelLp);return true;}return true;}});}
 public void onDestroy(){try{if(panel!=null)wm.removeView(panel);if(circle!=null)wm.removeView(circle);}catch(Exception ignored){}super.onDestroy();}
 class CircleView extends View {Paint p=new Paint(3);long start=0;int duration=8000;CircleView(Context c){super(c);p.setColor(Color.GREEN);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setAlpha(210);}void startAnimation(int s){start=System.currentTimeMillis();duration=s*1000;anim=true;invalidate();handler.post(tick);}Runnable tick=new Runnable(){public void run(){if(anim){invalidate();if(System.currentTimeMillis()-start<duration)handler.postDelayed(this,16);else anim=false;}}};protected void onDraw(Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f;float rad=radius; p.setColor(Color.argb(200,50,255,40));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);if(anim){float frac=Math.min(1f,(System.currentTimeMillis()-start)/(float)duration);c.drawArc(new RectF(cx-rad,cy-rad,cx+rad,cy+rad),-90,360*frac,false,p);p.setStyle(Paint.Style.FILL);p.setAlpha(35);c.drawCircle(cx,cy,rad,p);p.setAlpha(200);}else{c.drawCircle(cx,cy,rad,p);p.setStyle(Paint.Style.FILL);p.setAlpha(30);c.drawCircle(cx,cy,rad,p);p.setAlpha(200);} }}
}
